-- A retomada do diagrama antigo sai (as escolhas novas entram na chave de cada DFD).
DELETE FROM `automacao_progresso`
WHERE `fluxo_id` IN (SELECT `id` FROM `automacao_fluxos` WHERE `nome` = 'Verificar DFDs na Centi' AND `grafo` <> replace('{"v":1,"nos":[{"id":"inicio1","tipo":"gatilho.inicio","x":0,"y":160,"config":{}},{"id":"dfds1","tipo":"sistema.ler","x":280,"y":160,"config":{"objeto":"dfds","buscaDfds":"tabela","entrega":"lista","marcar":false}},{"id":"div1","tipo":"dados.filtrarConferencia","x":576,"y":160,"config":{"conteudo":true,"quais":"todos","corrigir":true,"situacao":true,"centro":true,"trocarUnidade":false,"semDfd":false}},{"id":"conf1","tipo":"fluxo.executar","x":872,"y":160,"config":{"modo":"porItem","paralelo":3,"retomar":true,"chave":"id","limite":20000,"fluxoId":"__FILHO__"}},{"id":"sem1","tipo":"centi.semDfd","x":872,"y":352,"config":{}}],"conexoes":[{"de":"inicio1","saida":"saida","para":"dfds1","entrada":"entrada"},{"de":"dfds1","saida":"saida","para":"div1","entrada":"entrada"},{"de":"div1","saida":"saida","para":"conf1","entrada":"entrada"},{"de":"div1","saida":"saida","para":"sem1","entrada":"entrada"}],"modelo":"conferir-corrigir-centi"}', '__FILHO__', (SELECT MIN(f.`id`) FROM `automacao_fluxos` f WHERE f.`nome` = 'Verificar 1 DFD na Centi' AND f.`criado_por` IS `automacao_fluxos`.`criado_por`)));
--> statement-breakpoint
