-- 3) A agenda: a única sem agenda recebe a da antiga ATIVA do mesmo dono (a de menor id).
UPDATE `automacao_fluxos`
SET (`frequencia`, `ativo`, `proxima_em`) = (
  SELECT a.`frequencia`, a.`ativo`, a.`proxima_em` FROM `automacao_fluxos` a
  WHERE a.`nome` IN ('Execução dos DFDs na CM002', 'Unidades dos DFDs × Centro de Custo da CM002') AND a.`ativo` = 1 AND a.`criado_por` IS `automacao_fluxos`.`criado_por`
  ORDER BY a.`id` LIMIT 1
)
WHERE `nome` = 'Verificar DFDs na Centi' AND `ativo` = 0
  AND EXISTS (SELECT 1 FROM `automacao_fluxos` a WHERE a.`nome` IN ('Execução dos DFDs na CM002', 'Unidades dos DFDs × Centro de Custo da CM002') AND a.`ativo` = 1 AND a.`criado_por` IS `automacao_fluxos`.`criado_por`);
--> statement-breakpoint
-- 4) As antigas saem (com a única do mesmo dono e sem uso como etapa) — o progresso delas cai pela cascata.
DELETE FROM `automacao_fluxos`
WHERE `nome` IN ('Execução dos DFDs na CM002', 'Unidades dos DFDs × Centro de Custo da CM002', 'Situação da CM002 numa coluna da Mesa')
  AND EXISTS (SELECT 1 FROM `automacao_fluxos` u WHERE u.`nome` = 'Verificar DFDs na Centi' AND u.`criado_por` IS `automacao_fluxos`.`criado_por`)
  AND NOT EXISTS (
    SELECT 1 FROM `automacao_fluxos` o
    WHERE o.`id` <> `automacao_fluxos`.`id`
      AND (o.`grafo` LIKE '%"fluxoId":"' || `automacao_fluxos`.`id` || '"%' OR o.`grafo` LIKE '%"fluxoId":' || `automacao_fluxos`.`id` || ',%' OR o.`grafo` LIKE '%"fluxoId":' || `automacao_fluxos`.`id` || '}%')
  );
